begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
insert into auth.users(id,email) values('91000000-0000-4000-8000-000000000001','oauth-fixture@example.invalid');
insert into public.businesses(id,name,slug) values('92000000-0000-4000-8000-000000000001','OAuth fixture','oauth-fixture');
select ok((select relrowsecurity from pg_class where oid='public.mp_seller_connections'::regclass),'token table has RLS');
select ok(not has_table_privilege('authenticated','public.mp_seller_connections','select'),'browser cannot read tokens');
select ok(not has_table_privilege('anon','public.mp_oauth_states','select'),'anonymous cannot read states');
select ok(not has_function_privilege('authenticated','public.mp_consume_oauth(text,text)','execute'),'browser cannot consume states');
select public.mp_begin_oauth('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','test','fixture-state','protected-fixture');
select is((select count(*)::int from public.mp_consume_oauth('fixture-state','production')),0,'wrong environment rejected');
select is((select count(*)::int from public.mp_consume_oauth('fixture-state','test')),1,'valid state consumed');
select is((select count(*)::int from public.mp_consume_oauth('fixture-state','test')),0,'replay rejected');
select public.mp_begin_oauth('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','test','expired-state','protected-fixture');
update public.mp_oauth_states set expires_at=now()-interval '1 second';
select is((select count(*)::int from public.mp_consume_oauth('expired-state','test')),0,'expired state rejected');
select ok(public.mp_finish_oauth('92000000-0000-4000-8000-000000000001','test',(select generation from public.mp_seller_connections where business_id='92000000-0000-4000-8000-000000000001'),'123456','999999','read write offline_access','encrypted-fixture',now()+interval '1 hour'),'connection saved');
select is((select count(*)::int from public.mp_claim_refresh('92000000-0000-4000-8000-000000000001','test','93000000-0000-4000-8000-000000000001')),1,'first refresh owns grant');
select is((select count(*)::int from public.mp_claim_refresh('92000000-0000-4000-8000-000000000001','test','93000000-0000-4000-8000-000000000002')),0,'concurrent refresh rejected');
select ok(not public.mp_finish_refresh('92000000-0000-4000-8000-000000000001','test','93000000-0000-4000-8000-000000000002',(select generation from public.mp_seller_connections where business_id='92000000-0000-4000-8000-000000000001'),'wrong',now()+interval '1 day','read'),'non-owner cannot rotate');
select public.mp_disconnect('92000000-0000-4000-8000-000000000001','test');
select is((select protected_tokens from public.mp_seller_connections where business_id='92000000-0000-4000-8000-000000000001'),null,'disconnect destroys token material');
select is((select status from public.mp_seller_connections where business_id='92000000-0000-4000-8000-000000000001'),'disconnected','disconnect persists');
select ok(not public.mp_finish_oauth('92000000-0000-4000-8000-000000000001','test','93000000-0000-4000-8000-000000000001','123456','999999','read','stale',now()+interval '1 day'),'stale callback cannot reconnect');
select * from finish();
rollback;
